# <<< SPEC

# >>> HINTS
# <<< HINTS

# >>> CHOICES
if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_command() {
    if _argc_util_has_path_prefix; then
        _argc_util_comp_path
        return 0
    fi
    _argc_util_comp_command
}

_choice_command_args() {
    if [[ "${#argc__positionals[@]}" -lt 2 ]]; then
        _choice_command
    else
        _argc_util_comp_subcommand 0
    fi
}

_choice_strict_control() {
    terragrunt info strict list 2>/dev/null | _argc_util_strip_ansi |
        gawk '{
            line=$0
            sub(/^[[:space:]]+/, "", line)
            match(line, /^[^[:space:]]+/)
            name=substr(line, 1, RLENGTH)
            rest=substr(line, RLENGTH+1)
            sub(/^[[:space:]]+[^[:space:]]+[[:space:]]+/, "", rest)
            if (name ~ /^[a-z][a-z0-9-]*$/) print name "\t" rest
        }'
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
